import java.util.*;

class Solution {
  public long minimumCost(int m, int n, int[] horizontalCut, int[] verticalCut) {
    Integer[] h = new Integer[horizontalCut.length];
    Integer[] v = new Integer[verticalCut.length];
    for (int i = 0; i < h.length; i++) h[i] = horizontalCut[i];
    for (int i = 0; i < v.length; i++) v[i] = verticalCut[i];
    Arrays.sort(h, Collections.reverseOrder());
    Arrays.sort(v, Collections.reverseOrder());
    int horizontalPieces = 1, verticalPieces = 1, i = 0, j = 0;
    long answer = 0;
    while (i < h.length || j < v.length) {
      if (j == v.length || (i < h.length && h[i] >= v[j])) {
        answer += (long) h[i++] * verticalPieces;
        horizontalPieces++;
      } else {
        answer += (long) v[j++] * horizontalPieces;
        verticalPieces++;
      }
    }
    return answer;
  }
}
